import {canonicalSha256} from '../core/canonical-json.mjs';import {scanAgentSurface} from './scanner.mjs';
export function planSecureInstall({packageRecord,currentPermissions=[]}={}){if(!packageRecord?.id||!packageRecord.revision||!/^[a-f0-9]{64}$/.test(String(packageRecord.digest)))throw new TypeError('Pinned package identity and digest are required');const scan=scanAgentSurface(packageRecord.surface??{});const desired=[];for(const hook of packageRecord.surface?.hooks??[])desired.push(`hook:${hook.event}`);for(const server of packageRecord.surface?.mcpServers??[])desired.push(`mcp:${server.id}`);for(const command of packageRecord.surface?.allowedCommands??[])desired.push(`command:${command}`);const previous=new Set(currentPermissions);const permissionDiff=[...new Set(desired)].filter(x=>!previous.has(x)).sort().map(permission=>({permission,change:'add'}));const highRisk=permissionDiff.some(x=>x.permission.startsWith('hook:')||x.permission.startsWith('mcp:'))||scan.status==='blocked';const payload={schemaVersion:1,packageId:packageRecord.id,revision:packageRecord.revision,digest:packageRecord.digest,license:packageRecord.license,scan,permissionDiff,status:scan.status==='blocked'?'blocked':highRisk?'approval-required':'ready'};return Object.freeze({...payload,planSha256:canonicalSha256(payload)});}
export function authorizeSecureInstall({plan,principal}={}){if(plan?.status==='blocked')throw new Error('Blocked package cannot be installed');if(principal?.type!=='human'||!principal.roles?.includes('security-admin'))throw new Error('Human security-admin approval is required');const subject={schemaVersion:1,status:'authorized',planSha256:plan.planSha256,packageId:plan.packageId,authorizedBy:principal.id,authorizedAt:new Date().toISOString()};return Object.freeze({...subject,installReceiptSha256:canonicalSha256(subject)});}
